26: /**
27:  * A subscriber method on a specific object, plus the executor that should be used for dispatching
28:  * events to it.
29:  *
30:  * <p>Two subscribers are equivalent when they refer to the same method on the same object (not
31:  * class). This property is used to ensure that no subscriber method is registered more than once.
32:  *
33:  * @author Colin Decker
34:  */
35: class Subscriber {
36: 
37:   /** Creates a {@code Subscriber} for {@code method} on {@code listener}. */
38:   static Subscriber create(EventBus bus, Object listener, Method method) {
39:     return isDeclaredThreadSafe(method)
40:         ? new Subscriber(bus, listener, method)
41:         : new SynchronizedSubscriber(bus, listener, method);
42:   }
43: 
44:   /** The event bus this subscriber belongs to. */
45:   @Weak private final EventBus bus;
46: 
47:   /** The object with the subscriber method. */
48:   @VisibleForTesting final Object target;
49: 
50:   /** Subscriber method. */
51:   private final Method method;
52: 
53:   /** Executor to use for dispatching events to this subscriber. */
54:   private final Executor executor;
55: 
56:   private Subscriber(EventBus bus, Object target, Method method) {
57:     this.bus = bus;
58:     this.target = checkNotNull(target);
59:     this.method = method;
60:     method.setAccessible(true);
61: 
62:     this.executor = bus.executor();
63:   }
64: 
65:   /** Dispatches {@code event} to this subscriber using the proper executor. */
66:   final void dispatchEvent(Object event) {
67:     executor.execute(
68:         () -> {
69:           try {
70:             invokeSubscriberMethod(event);
71:           } catch (InvocationTargetException e) {
72:             bus.handleSubscriberException(e.getCause(), context(event));
73:           }
74:         });
75:   }
76: 
77:   /**
78:    * Invokes the subscriber method. This method can be overridden to make the invocation
79:    * synchronized.
80:    */
81:   @VisibleForTesting
82:   void invokeSubscriberMethod(Object event) throws InvocationTargetException {
83:     try {
84:       method.invoke(target, checkNotNull(event));
85:     } catch (IllegalArgumentException e) {
86:       throw new Error("Method rejected target/argument: " + event, e);
87:     } catch (IllegalAccessException e) {
88:       throw new Error("Method became inaccessible: " + event, e);
89:     } catch (InvocationTargetException e) {
90:       if (e.getCause() instanceof Error) {
91:         throw (Error) e.getCause();
92:       }
93:       throw e;
94:     }
95:   }
96: 
97:   /** Gets the context for the given event. */
98:   private SubscriberExceptionContext context(Object event) {
99:     return new SubscriberExceptionContext(bus, event, target, method);
100:   }
101: 
102:   @Override
103:   public final int hashCode() {
104:     return (31 + method.hashCode()) * 31 + System.identityHashCode(target);
105:   }
106: 
107:   @SuppressWarnings("ReferenceEquality") // see comment below
108:   @Override
109:   public final boolean equals(@Nullable Object obj) {
110:     if (obj instanceof Subscriber) {
111:       Subscriber that = (Subscriber) obj;
112:       // Use == so that different equal instances will still receive events.
113:       // We only guard against the case that the same object is registered
114:       // multiple times
115:       return target == that.target && method.equals(that.method);
116:     }
117:     return false;
118:   }
119: 
120:   /**
121:    * Checks whether {@code method} is thread-safe, as indicated by the presence of the {@link
122:    * AllowConcurrentEvents} annotation.
123:    */
124:   private static boolean isDeclaredThreadSafe(Method method) {
125:     return method.getAnnotation(AllowConcurrentEvents.class) != null;
126:   }
127: 
128:   /**
129:    * Subscriber that synchronizes invocations of a method to ensure that only one thread may enter
130:    * the method at a time.
131:    */
132:   @VisibleForTesting
133:   static final class SynchronizedSubscriber extends Subscriber {
134: 
135:     private SynchronizedSubscriber(EventBus bus, Object target, Method method) {
136:       super(bus, target, method);
137:     }
138: 
139:     @Override
140:     void invokeSubscriberMethod(Object event) throws InvocationTargetException {
141:       synchronized (this) {
142:         super.invokeSubscriberMethod(event);
143:       }
144:     }
145:   }
146: }
